  "ch1.read.p": "Probability from the amplitudes",
  "ch1.read.n": "Measured",
  "ch1.unit.polar": "{m} × e^(i·{d}°)",
  "ch1.unit.prob": "“{o}” {p}%",
  "ch1.unit.count": "“{o}” {k} / {n}",
  "ch1.out.z0": "0", "ch1.out.z1": "1",
