  "ch3.read.exact": "Theoretical win rate at these angles",
  "ch3.read.bob": "Bob on his own: share answering 1 (Alice uses angle one / angle two)",
  "ch3.unit.deg": "{v}°",
  "ch3.unit.bob": "{a}% / {b}%",
  "ch3.cv.alice": "Alice",
  "ch3.cv.bob": "Bob",
